"""Serial log capture for the SB-40 test rig."""
import re
import time
from dataclasses import dataclass

import serial

BOOT_BANNER = re.compile(r"^SB40 boot (\d+\.\d+\.\d+)")
FAULT = re.compile(r"(HardFault|WDT reset|E\d{2})")


@dataclass
class Capture:
    port: str
    baud: int = 115200
    lines: list[str] | None = None

    def version(self) -> str | None:
        """Bootloader version from the banner, if it was captured."""
        for line in self.lines or []:
            m = BOOT_BANNER.match(line)
            if m:
                return m.group(1)
        return None


def open_port(port: str, baud: int = 115200) -> serial.Serial:
    """Open the rig's USB-serial adapter with a short read timeout."""
    return serial.Serial(port, baud, timeout=0.2)


def capture(port: str, seconds: float = 5.0, baud: int = 115200) -> Capture:
    """Read lines for `seconds` and return them with the port settings."""
    cap = Capture(port, baud, [])
    with open_port(port, baud) as ser:
        end = time.monotonic() + seconds
        while time.monotonic() < end:
            raw = ser.readline()
            if raw:
                cap.lines.append(raw.decode("utf-8", "replace").rstrip())
    return cap


def first_fault(cap: Capture) -> tuple[int, str] | None:
    """Line number and text of the first fault marker, or None."""
    for n, line in enumerate(cap.lines or [], start=1):
        if FAULT.search(line):
            return n, line
    return None


class Rig:
    """The bench rig: one serial port and a power relay on GPIO 17."""

    def __init__(self, port: str):
        self.port = port

    def power_cycle(self, off_s: float = 1.0) -> None:
        """Switch the DUT off for off_s seconds, then on again."""
        raise NotImplementedError

    def boot_log(self, seconds: float = 8.0) -> Capture:
        """Power-cycle the DUT and capture its boot log."""
        self.power_cycle()
        return capture(self.port, seconds)
